const practiceBody = `{"status":"solved","help_used":"hint","solved_on":"2026-11-09T20:30:00.120+06:00","time_spent":2100,"notes":"Keep this note"}`

// Verify HTTP add and PATCH preserve omitted practice values and clear explicitly supplied nulls.
// Generated by Codex and not thoroughly checked for correctness.
func TestPracticeHandlersPreserveAndClearFields(t *testing.T) {
	gin.SetMode(gin.TestMode)
	repository := newMockRepository()
	repository.expectedContext = t.Context()
	router := newListHandlerTestRouter(repository)
	addBody := `{"items":[{"problem_id":" ` + testProblemID + ` ",` + practiceBody[1:] + `]}`
	added := performListRequest(t.Context(), router, http.MethodPost, itemCollectionPath(testListID), addBody)
	assertResponseStatus(t, added, http.StatusOK)
	want := newListItemFixture()
	if err := json.Unmarshal([]byte(practiceBody), &want.Practice); err != nil {
		t.Fatal(err)
	}
	solvedUTC := "2026-11-09T14:30:00.12Z"
	want.SolvedOn = &solvedUTC
	assertJSONBody(t, added, listitems.CollectionResult{Added: []listitems.ListItem{want}, Order: []listitems.OrderedItem{{ProblemID: testProblemID, Position: want.Position}}})
	duplicate := performListRequest(t.Context(), router, http.MethodPost, itemCollectionPath(testListID), `{"items":[{"problem_id":"`+testProblemID+`","status":"not_started","notes":null}]}`)
	assertResponseStatus(t, duplicate, http.StatusOK)
	assertJSONBody(t, duplicate, listitems.CollectionResult{Duplicates: []string{testProblemID}, Order: []listitems.OrderedItem{}})
	if !reflect.DeepEqual(repository.items[testListID][testProblemID], want) {
		t.Fatal("duplicate add changed the saved item")
	}

	path := itemPath(testListID, testProblemID)
	response := performListRequest(t.Context(), router, http.MethodPatch, path, `{"status":"in_progress"}`)
	assertResponseStatus(t, response, http.StatusOK)
	status := listitems.StatusInProgress
	want.Status = &status
	want.UpdatedAt = testItemCreatedAt().Add(time.Hour)
	assertJSONBody(t, response, testutil.APIResponse{Message: "Item updated", Item: want})
	response = performListRequest(t.Context(), router, http.MethodPatch, path, `{"notes":"","time_spent":0,"help_used":"none"}`)
	assertResponseStatus(t, response, http.StatusOK)
	seconds := int64(0)
	help := listitems.HelpNone
	want.Notes, want.TimeSpent, want.HelpUsed = nil, &seconds, &help
	assertJSONBody(t, response, testutil.APIResponse{Message: "Item updated", Item: want})
	response = performListRequest(t.Context(), router, http.MethodPatch, path, `{"status":null,"help_used":null,"solved_on":null,"time_spent":null,"notes":null}`)
	assertResponseStatus(t, response, http.StatusOK)
	want.Practice = listitems.Practice{}
	assertJSONBody(t, response, testutil.APIResponse{Message: "Item updated", Item: want})
	removed := performListRequest(t.Context(), router, http.MethodPost, itemCollectionPath(testListID)+"/remove", `{"problem_ids":[" `+testProblemID+` "]}`)
	assertResponseStatus(t, removed, http.StatusOK)
	assertJSONBody(t, removed, listitems.CollectionResult{Removed: []string{testProblemID}, Order: []listitems.OrderedItem{}})
	if repository.contextMismatch {
		t.Fatal("practice handlers did not pass request context")
	}
}

// Verify invalid practice values are rejected without changing repository state.
// Generated by Codex and not thoroughly checked for correctness.
func TestPracticeHandlersRejectInvalidRequestsWithoutMutation(t *testing.T) {
	for _, testCase := range []struct {
		name, body string
	}{
		{"invalid status", `{"status":"skipped"}`},
		{"invalid help", `{"help_used":"other"}`},
		{"invalid solve timestamp", `{"solved_on":"2026-02-30T10:00:00Z"}`},
		{"negative time", `{"time_spent":-1}`},
		{"fractional time", `{"time_spent":0.5}`},
		{"overflow time", `{"time_spent":2147483648}`},
		{"overlong notes", fmt.Sprintf(`{"notes":%q}`, strings.Repeat("界", 513))},
	} {
		for _, method := range []string{http.MethodPost, http.MethodPatch} {
			t.Run(testCase.name+" "+method, func(t *testing.T) {
				gin.SetMode(gin.TestMode)
				repository := newMockRepository()
				original := newListItemFixture()
				repository.storeItem(original)
				path, body := itemPath(testListID, testProblemID), testCase.body
				if method == http.MethodPost {
					path = itemCollectionPath(testListID)
					body = `{"items":[{"problem_id":"` + testProblemID + `",` + body[1:] + `]}`
				}
				response := performListRequest(t.Context(), newListHandlerTestRouter(repository), method, path, body)
				assertResponseStatus(t, response, http.StatusBadRequest)
				if len(repository.calls) != 0 || !reflect.DeepEqual(repository.items[testListID][testProblemID], original) {
					t.Fatal("invalid practice request reached repository or changed item")
				}
			})
		}
	}
}

// Generated by Codex and not thoroughly checked for correctness.
func TestPatchMatchesEncodedProblemID(t *testing.T) {
	gin.SetMode(gin.TestMode)
	const problemID = "judge:A+B%2F"
	repository := newMockRepository()
	router := newListHandlerTestRouter(repository)
	body := fmt.Sprintf(`{"items":[{"problem_id":%q}]}`, problemID)
	add := performListRequest(t.Context(), router, http.MethodPost, itemCollectionPath(testListID), body)
	assertResponseStatus(t, add, http.StatusOK)
	patch := performListRequest(t.Context(), router, http.MethodPatch, itemPath(testListID, problemID), `{"notes":"updated"}`)
	assertResponseStatus(t, patch, http.StatusOK)
	saved := repository.items[testListID][problemID]
	if saved.ProblemId != problemID || saved.Notes == nil || *saved.Notes != "updated" {
		t.Fatalf("PATCH did not update the exact problem key: %+v", saved)
	}
}

// Verify strict PATCH decoding, ownership failures, and stable repository-error responses.
// Generated by Codex and not thoroughly checked for correctness.
func TestItemPatchErrors(t *testing.T) {
	for _, testCase := range []struct {
		name, listID, problemID, body, message string
		setup                                  func(*mockRepository)
		status                                 int
	}{
		{"empty patch", "7", testProblemID, `{}`, testInvalidFormatMessage, nil, 400},
		{"null patch", "7", testProblemID, `null`, testInvalidFormatMessage, nil, 400},
		{"unknown field", "7", testProblemID, `{"initialize_only":true}`, testInvalidFormatMessage, nil, 400},
		{"position cannot be patched", "7", testProblemID, `{"position":2}`, testInvalidFormatMessage, nil, 400},
		{"trailing body", "7", testProblemID, `{"notes":"x"} {}`, testInvalidFormatMessage, nil, 400},
		{"malformed trailing content", "7", testProblemID, `{"notes":"x"} garbage`, testInvalidFormatMessage, nil, 400},
		{"malformed JSON", "7", testProblemID, `{"notes":`, testInvalidFormatMessage, nil, 400},
		{"malformed list ID", "invalid", testProblemID, `{"notes":"x"}`, testInvalidListIDMessage, nil, 400},
		{"missing item", "7", "absent", `{"notes":"x"}`, "Item does not exist", nil, 404},
		{"foreign list", "7", testProblemID, `{"notes":"x"}`, "Item does not exist", clearLists, 404},
		{"repository error", "7", testProblemID, `{"notes":"x"}`, "Failed to update item", operationFailure(updateListItemOperation), 500},
	} {
		t.Run(testCase.name, func(t *testing.T) {
			gin.SetMode(gin.TestMode)
			repository := newMockRepository()
			repository.storeItem(newListItemFixture())
			repository.expectedContext = t.Context()
			if testCase.setup != nil {
				testCase.setup(repository)
			}
			response := performListRequest(t.Context(), newListHandlerTestRouter(repository), http.MethodPatch, itemPath(testCase.listID, testCase.problemID), testCase.body)
			assertResponseStatus(t, response, testCase.status)
			assertJSONBody(t, response, errorBody(testCase.message))
		})
	}
}
